  RepoMigration(id: "20261204000000_admin_dashboard", description: "Backend for the web admin dashboard. Adds account deactivation and a 30-day removal window as new nullable columns, and staff-only functions: overview, user search and detail, direct actions without a report (warn, restrict, suspend, ban, deactivate, reactivate, remove, cancel removal), unsuspend, list of suspended accounts, audit log and staff management. Moderators can warn, restrict, suspend and unsuspend; only admins can ban, remove and manage staff. Every action is written to moderation_actions and access_audit_log.", tables: "none created (columns added to public.profiles)", columns: "profiles.deactivated_at, profiles.removal_due_at, profiles.deactivation_reason", compat: "Additive. Existing functions keep their signatures. active_restriction() additionally reports 'suspended' for a deactivated profile, so existing gates (requests, messages, discovery) apply with no app change.", recovery: "drop the mod_*/admin_* functions added here; the three nullable columns can stay unused.", userData: "none changed. \"Remove\" only marks an account (hidden at once, 30-day recovery); nothing is deleted here."),
