  RepoMigration(id: "20261207000000_message_receipts", description: "Fixes saving \"read\" on the server (an outdated guard made every message update fail) and adds real delivery and read receipts for chat. Each message now records when it reached the other person's device (delivered_at), when it was read (read_at) and, for voice notes, when it was played (listened_at). Times are set by the server, never by a phone. The existing is_read flag keeps working: marking a message read (by an older or newer app) also fills read_at and delivered_at.", tables: "public.messages (columns added)", columns: "messages.delivered_at, messages.read_at, messages.listened_at", compat: "Additive. is_read and its update policy are unchanged; older apps keep working and simply do not report \"delivered\".", recovery: "drop trigger messages_receipts on public.messages; drop function public.tg_message_receipts(); drop function public.mark_delivered(uuid[]); drop function public.mark_listened(uuid); alter table public.messages drop column delivered_at, drop column read_at, drop column listened_at;", userData: "none changed. Existing messages that are already read get read_at = created_at as a floor only for display."),
  RepoMigration(id: "20261208000000_scheduled_messages", description: "Scheduled messages that are delivered by the server, so they are sent at the chosen time even if the sender's phone is off, offline, logged out or the app is closed. Chats are end-to-end encrypted, so the sender's phone encrypts the message when scheduling it (exactly as for a normal send) and the server only stores and releases that ciphertext; it never sees the text. A job runs every 15 seconds (pg_cron), is idempotent (one row per client message id; delivery inserts at most one message), retries failures with back-off and survives restarts because everything lives in the database.", tables: "public.scheduled_messages (new)", columns: "none", compat: "Additive. send_message and the messages table are unchanged; the recipient receives a normal message.", recovery: "select cron.unschedule('vouby-deliver-scheduled'); drop function public.schedule_message(uuid, uuid, uuid, jsonb, timestamptz, text), public.cancel_scheduled_message(uuid), public.my_scheduled_messages(uuid), public.service_deliver_scheduled(); drop table public.scheduled_messages;", userData: "none changed"),
  RepoMigration(id: "20261209000000_support_system", description: "Complete Help & Support. (1) Tickets get the full status set (new, open, assigned, in progress, waiting for user, escalated, resolved, closed), a priority, an assignee, app/device details, the linked chatbot conversation, a rating and reopen support; staff get internal notes and the actions to assign, escalate and change priority. (2) A chatbot whose answers, keywords, quick replies, welcome and fallback messages are stored in the database and edited by admins, so changes reach the app at once; its conversations are kept. (3) In-app notifications can no longer be duplicated (dedupe_key). (4) Two more report categories (threats, privacy violation) and a priority for serious reports. Nothing is deleted or rewritten; older app versions keep working.", tables: "public.support_ticket_notes, public.support_bot_settings, public.support_bot_replies, public.support_bot_conversations (new); public.support_tickets, public.user_notifications (columns added)", columns: "support_tickets.priority/assigned_to/app_version/device_info/bot_conversation_id/rating/rating_comment/rated_at/ resolved_at/closed_at/reopened_count, user_notifications.dedupe_key", compat: "Additive. The status/category/reason checks are widened (every old value stays valid). Existing functions keep their signatures; submit_support_ticket, reply_to_ticket and mod_set_ticket_status still work.", recovery: "drop the new functions and tables; the added columns can stay unused; restore the old check lists if needed.", userData: "none changed"),
  RepoMigration(id: "20261210000000_presence_offline", description: "\"Online\" now ends the moment the app is closed or the screen is locked, like WhatsApp. A phone says \"I left\" (presence_offline) and \"I'm back\" (presence_ping); the other person's app asks peer_presence_v2 and gets the last-seen time plus an online flag (online only when the person did not leave and was active in the last 90 seconds). The old touch_presence / peer_presence functions are untouched, so older app versions keep working.", tables: "public.user_presence (column added)", columns: "user_presence.offline_at (timestamptz, nullable)", compat: "Additive. Old apps keep using touch_presence and peer_presence with their 2-minute rule.", recovery: "drop function public.presence_ping(); drop function public.presence_offline(); drop function public.peer_presence_v2(uuid); alter table public.user_presence drop column offline_at;", userData: "none changed. Existing rows keep last_active_at; offline_at starts empty."),
